using System;using System.Linq;using System.Collections.Generic;using BeamScheduleFormatter;
class PowOpenAndIssuesTests {
 static int checks;static void Check(bool ok,string why){checks++;if(!ok)throw new Exception(why);}
 static void Main(){string saved="<ProgramOfWorks computedInputsKnown='False'><Footings/><BackupBill/><BackupBillRoutes/><SourceFileManifest version='1'/></ProgramOfWorks>";string linked="<ProgramOfWorks computedInputsKnown='False'><Footings/><BackupBill><Item slot='x' signature='s' code='900' workbook='123'/></BackupBill><BackupBillRoutes><Route key='a' slot='x'/></BackupBillRoutes><SourceFileManifest version='1'><File kind='Excel workbook (imported original)' id='copy'/></SourceFileManifest></ProgramOfWorks>";Check(!PowOpenState.HasInputChanges(linked,saved),"Catalogue, cached workbook quantity, routes and selected workbook copy do not block Open");Check(PowOpenState.HasInputChanges(linked.Replace("<Footings/>","<Footings><Entry c0='F1' c2='2'/></Footings>"),saved),"Actual measurements remain protected");Check(PowOpenState.HasInputChanges(linked.Replace("workbook='123'","manual='12.5'"),saved),"Manual BOQ overrides remain protected");Check(PowOpenState.HasInputChanges(linked.Replace("kind='Excel workbook (imported original)'","kind='Project attachment'"),saved),"Unrelated added references remain protected");Check(PowOpenState.HasInputChanges(linked.Replace("computedInputsKnown='False'","computedInputsKnown='True'"),saved),"Calculated-input state is not silently ignored");/* Input issues are listed in the app under the Bill of Quantities, not written to Excel (17 November 2026). */var used=new HashSet<string>(StringComparer.OrdinalIgnoreCase){"ANG-001","ANG-002","CUSTOM"};int counter=0;Check(StructuralSteelIds.Next("ANG",used,ref counter)=="ANG-003","Automatic IDs avoid existing names");Check(StructuralSteelIds.Next("ANG",used,ref counter)=="ANG-004","IDs advance without changing existing IDs");Check(used.Contains("CUSTOM"),"Existing custom ID preserved");var targetA=new BackupTarget{SlotId="bad",Code="1",Description="Bad input item",Unit="m3"};var targetB=new BackupTarget{SlotId="good",Code="2",Description="Valid item",Unit="m3"};var a=new BackupDemand{Key="A",Quantity=4};var b=new BackupDemand{Key="B",Quantity=5};var plan=new BackupWritePlan{Demands=new List<BackupDemand>{a,b},Targets=new List<BackupTarget>{targetA,targetB},Routes=new Dictionary<string,BackupTarget>{{"A",targetA},{"B",targetB}}};PowIssueOutput.ExcludeTargets(plan,new[]{"bad"});Check(plan.Demands.Count==1&&plan.Demands[0]==b&&plan.Routes.ContainsKey("B"),"Invalid manual target is omitted while other valid demands can sync");var invalid=new BackupBillItem{Slot="bad",Code="1",Description="Bad quantity",Unit="m3",Row=10,ManualInputText="not a number"};invalid.Signature=BackupMapping.Identity(invalid.Target);var doc=new System.Xml.XmlDocument();doc.LoadXml("<ProgramOfWorks/>");BackupBill.Write(doc.DocumentElement,new[]{invalid});var roundtrip=BackupBill.Read(doc.DocumentElement).Single();Check(roundtrip.ManualInputText=="not a number"&&!roundtrip.ManualQuantity.HasValue,"Invalid manual BOQ input survives save/open as text");Check(roundtrip.ManualDemand()==null,"Invalid manual quantity cannot silently overwrite Excel");Check(PowOpenState.HasInputChanges(linked.Replace("workbook='123'","manualInput='bad'"),saved),"Invalid manual text remains protected before Open");Console.WriteLine("PASS: "+checks+" link-before-open input protection, partial-output issues and steel ID checks");}
}
